import{_ as l,o as i,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Testing Meeting 2018-10-03","description":"","frontmatter":{"title":"Ceph Testing Meeting 2018-10-03","date":"2018-10-03T00:00:00.000Z","updated":"2018-10-18T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH 算法","高可用性","可扩展性","对象存储","块存储","文件系统存储","数据一致性","去中心化","性能","Bluestore","Bluefs","Rocksdb","OSD","MON","MDS","PG","RADOS","librados","libcephfs","cephfs","rbd","radosgw","RGW","RESTful API","认证","授权","加密","纠错编码","复制","快照","克隆","薄分配","iSCSI","Fibre Channel","NFS","CIFS","POSIX","监控","仪表板","管理","编排","自动化","集成","容器化","Kubernetes","Docker","虚拟化","云计算","AWS","Azure","Google Cloud","混合云","多云","存储集群","节点","磁盘","SSD","HDD","JBOD","SAN","NAS","网络","网络拓扑","失效域","恢复","弹性","负载均衡","缓存","压缩","数据去重","分层存储","性能调优","基准测试","测试","验证"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Ceph_Testing_Meeting_2018-10-03.md","filePath":"posts/2018/Ceph_Testing_Meeting_2018-10-03.md","lastUpdated":1780460162000}'),s={name:"posts/2018/Ceph_Testing_Meeting_2018-10-03.md"};function o(n,e,r,p,u,h){return i(),a("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间" tabindex="-1">会议时间： <a class="header-anchor" href="#会议时间" aria-label="Permalink to &quot;会议时间：&quot;">​</a></h4><p>[此处填写会议时间]</p><h4 id="参会人员" tabindex="-1">参会人员： <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员：&quot;">​</a></h4><p>[此处填写参会人员名单]</p><h4 id="会议内容" tabindex="-1">会议内容： <a class="header-anchor" href="#会议内容" aria-label="Permalink to &quot;会议内容：&quot;">​</a></h4><p><strong>1. 问候与自我介绍</strong></p><ul><li>会议开始，与会者互相问候，并介绍了自己的工作地点和近况。</li></ul><p><strong>2. 主题讨论</strong></p><ul><li><p><strong>议题一：Ceph 存储请求</strong></p><ul><li>有成员提到一个存储请求（pool request）已经两周没有回应，需要跟进。</li><li>另一个成员提到有多个与 openSUSE 相关的池请求，建议同时测试。</li></ul></li><li><p><strong>议题二：Ansible 项目</strong></p><ul><li>有成员提到 Ansible 项目目前使用人数不多，预计在一周内处理。</li><li>有成员询问关于 openSUSE leap 的 OPR Insaf（OpenStack Provider Resource）请求，希望得到评审意见。</li></ul></li><li><p><strong>议题三：配置管理</strong></p><ul><li>讨论了如何支持多种操作系统和版本，以及如何使用 symbolic link 从配置集合中选取特定配置。</li></ul></li><li><p><strong>议题四：操作系统选择</strong></p><ul><li>讨论了是否支持所有操作系统或随机选择，以及在使用配置管理工具时如何处理操作系统配置。</li></ul></li><li><p><strong>议题五：Luminess 项目</strong></p><ul><li>有成员提到 Luminess 项目中的 sleep before teardown 特性需要重构，以便与并行和顺序执行兼容。</li></ul></li></ul><p><strong>3. 行动计划</strong></p><ul><li>跟进存储请求，确保及时得到回应。</li><li>处理 Ansible 项目，在一周内完成。</li><li>完成openSUSE leap的 OPR Insaf 请求的评审。</li><li>研究操作系统选择问题，并优化配置管理。</li><li>重构 Luminess 项目中的 sleep before teardown 特性。</li></ul><h4 id="会议总结" tabindex="-1">会议总结： <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;会议总结：&quot;">​</a></h4><p>本次会议讨论了 Ceph 存储请求、Ansible 项目、配置管理和操作系统选择等问题，并制定了相应的行动计划。会议气氛积极，大家积极参与讨论，为项目的顺利进行提供了有力保障。</p><h4 id="下次会议时间" tabindex="-1">下次会议时间： <a class="header-anchor" href="#下次会议时间" aria-label="Permalink to &quot;下次会议时间：&quot;">​</a></h4><p>[此处填写下一次会议时间]</p>',16)])])}const g=l(s,[["render",o]]);export{c as __pageData,g as default};
